<?php require_once __DIR__.'/../config/database.php';header('Content-Type: application/json');$s=strtoupper(trim($_GET['symbol']??''));$period=$_GET['period']??'5y';$allowed=['1d'=>1,'5d'=>5,'1mo'=>30,'6mo'=>180,'1y'=>365,'5y'=>1825,'max'=>99999];if(!preg_match('/^[A-Z0-9.\-^=]{1,20}$/',$s)||!isset($allowed[$period])){http_response_code(400);exit(json_encode(['error'=>'Invalid request']));}$st=db()->prepare('SELECT p.date,p.open,p.high,p.low,p.close,p.volume FROM prices p JOIN stocks s ON s.id=p.stock_id WHERE s.ticker=? AND p.date>=DATE_SUB(CURDATE(),INTERVAL ? DAY) ORDER BY p.date');$st->execute([$s,$allowed[$period]]);echo json_encode(['rows'=>$st->fetchAll()]);